import { Component, HostListener, OnInit } from '@angular/core';

@Component({
  selector: 'app-root',
  templateUrl: './app.component.html',
  styleUrls: ['./app.component.css']
})
export class AppComponent implements OnInit {
  title = 'angular';

  ngOnInit() {
    this.onScroll(); // Check initial state
  }

  @HostListener('window:scroll', [])
  onScroll() {
    const navbar = document.getElementById('navbar');
    const logoImg = document.getElementById('nav-logo') as HTMLImageElement;
    const userIconImg = document.getElementById('nav-user-icon') as HTMLImageElement;

    if (navbar) {
      if (window.scrollY > 50) {
        navbar.classList.add('scrolled');
        if (logoImg && logoImg.dataset.scrolled) {
          logoImg.src = logoImg.dataset.scrolled;
        }
        if (userIconImg && userIconImg.dataset.scrolled) {
          userIconImg.src = userIconImg.dataset.scrolled;
        }
      } else {
        navbar.classList.remove('scrolled');
        if (logoImg && logoImg.dataset.default) {
          logoImg.src = logoImg.dataset.default;
        }
        if (userIconImg && userIconImg.dataset.default) {
          userIconImg.src = userIconImg.dataset.default;
        }
      }
    }
  }
}
